2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
procfs: fix possible double mmput() in do_procmap_query()

When user provides incorrectly sized buffer for build ID for PROCMAP_QUERY
we return with -ENAMETOOLONG error.  After recent changes this condition
happens later, after we unlocked mmap_lock/per-VMA lock and did mmput(),
so original goto out is now wrong and will double-mmput() mm_struct.  Fix
by jumping further to clean up only vm_file and name_buf.

Link: https://lkml.kernel.org/r/20260210192738.3041609-1-andrii@kernel.org
Fixes: b5cbacd7f86f ("procfs: avoid fetching build ID while holding VMA lock")
Signed-off-by: Andrii Nakryiko <andrii@kernel.org>
Reported-by: Ruikai Peng <ruikai@pwno.io>
Reported-by: Thomas Gleixner <tglx@kernel.org>
Tested-by: Thomas Gleixner <tglx@kernel.org>
Reviewed-by: Shakeel Butt <shakeel.butt@linux.dev>
Reported-by: syzbot+237b5b985b78c1da9600@syzkaller.appspotmail.com
Cc: Ruikai Peng <ruikai@pwno.io>
Closes: https://lkml.kernel.org/r/CAFD3drOJANTZPuyiqMdqpiRwOKnHwv5QgMNZghCDr-WxdiHvMg@mail.gmail.com
Closes: https://lore.kernel.org/all/698aaf3c.050a0220.3b3015.0088.GAE@google.com/T/#u
Cc: <stable@vger.kernel.org>
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>

Here is the root cause:
After a commit that moved the build ID size check to later in do_procmap_query(), after the VMA locks have been released and mmput() has been called, the error path for -ENAMETOOLONG still jumped to the 'out' label, which then redundantly called query_vma_teardown() and mmput() again, causing a double mmput() (and potential double lock release). The refactoring did not update the goto target accordingly.

Here is the patch:

 static int do_procmap_query(struct mm_struct *mm, void __user *uarg)
 {
 	struct proc_maps_locking_ctx lock_ctx = { .mm = mm };
 	struct procmap_query karg;
 	struct vm_area_struct *vma;
 	struct file *vm_file = NULL;
 	const char *name = NULL;
 	char build_id_buf[BUILD_ID_SIZE_MAX], *name_buf = NULL;
 	__u64 usize;
 	int err;

 	if (copy_from_user(&usize, (void __user *)uarg, sizeof(usize)))
 		return -EFAULT;
 	/* argument struct can never be that large, reject abuse */
 	if (usize > PAGE_SIZE)
 		return -E2BIG;
 	/* argument struct should have at least query_flags and query_addr fields */
 	if (usize < offsetofend(struct procmap_query, query_addr))
 		return -EINVAL;
 	err = copy_struct_from_user(&karg, sizeof(karg), uarg, usize);
 	if (err)
 		return err;

 	/* reject unknown flags */
 	if (karg.query_flags & ~PROCMAP_QUERY_VALID_FLAGS_MASK)
 		return -EINVAL;
 	/* either both buffer address and size are set, or both should be zero */
 	if (!!karg.vma_name_size != !!karg.vma_name_addr)
 		return -EINVAL;
 	if (!!karg.build_id_size != !!karg.build_id_addr)
 		return -EINVAL;

 	if (!mm || !mmget_not_zero(mm))
 		return -ESRCH;

 	err = query_vma_setup(&lock_ctx);
 	if (err) {
 		mmput(mm);
 		return err;
 	}

 	vma = query_matching_vma(&lock_ctx, karg.query_addr, karg.query_flags);
 	if (IS_ERR(vma)) {
 		err = PTR_ERR(vma);
 		vma = NULL;
 		goto out;
 	}

 	karg.vma_start = vma->vm_start;
 	karg.vma_end = vma->vm_end;

 	karg.vma_flags = 0;
 	if (vma->vm_flags & VM_READ)
 		karg.vma_flags |= PROCMAP_QUERY_VMA_READABLE;
 	if (vma->vm_flags & VM_WRITE)
 		karg.vma_flags |= PROCMAP_QUERY_VMA_WRITABLE;
 	if (vma->vm_flags & VM_EXEC)
 		karg.vma_flags |= PROCMAP_QUERY_VMA_EXECUTABLE;
 	if (vma->vm_flags & VM_MAYSHARE)
 		karg.vma_flags |= PROCMAP_QUERY_VMA_SHARED;

 	karg.vma_page_size = vma_kernel_pagesize(vma);

 	if (vma->vm_file) {
 		const struct inode *inode = file_user_inode(vma->vm_file);

 		karg.vma_offset = ((__u64)vma->vm_pgoff) << PAGE_SHIFT;
 		karg.dev_major = MAJOR(inode->i_sb->s_dev);
 		karg.dev_minor = MINOR(inode->i_sb->s_dev);
 		karg.inode = inode->i_ino;
 	} else {
 		karg.vma_offset = 0;
 		karg.dev_major = 0;
 		karg.dev_minor = 0;
 		karg.inode = 0;
 	}

 	if (karg.vma_name_size) {
 		size_t name_buf_sz = min_t(size_t, PATH_MAX, karg.vma_name_size);
 		const struct path *path;
 		const char *name_fmt;
 		size_t name_sz = 0;

 		get_vma_name(vma, &path, &name, &name_fmt);

 		if (path || name_fmt || name) {
 			name_buf = kmalloc(name_buf_sz, GFP_KERNEL);
 			if (!name_buf) {
 				err = -ENOMEM;
 				goto out;
 			}
 		}
 		if (path) {
 			name = d_path(path, name_buf, name_buf_sz);
 			if (IS_ERR(name)) {
 				err = PTR_ERR(name);
 				goto out;
 			}
 			name_sz = name_buf + name_buf_sz - name;
 		} else if (name || name_fmt) {
 			name_sz = 1 + snprintf(name_buf, name_buf_sz, name_fmt ?: "%s", name);
 			name = name_buf;
 		}
 		if (name_sz > name_buf_sz) {
 			err = -ENAMETOOLONG;
 			goto out;
 		}
 		karg.vma_name_size = name_sz;
 	}

 	if (karg.build_id_size && vma->vm_file)
 		vm_file = get_file(vma->vm_file);

 	/* unlock vma or mmap_lock, and put mm_struct before copying data to user */
 	query_vma_teardown(&lock_ctx);
 	mmput(mm);

 	if (karg.build_id_size) {
 		__u32 build_id_sz;

 		if (vm_file)
 			err = build_id_parse_file(vm_file, build_id_buf, &build_id_sz);
 		else
 			err = -ENOENT;
 		if (err) {
 			karg.build_id_size = 0;
 		} else {
 			if (karg.build_id_size < build_id_sz) {
 				err = -ENAMETOOLONG;
-				goto out;
+				goto out_file;
 			}
 			karg.build_id_size = build_id_sz;
 		}
 	}

 	if (vm_file)
 		fput(vm_file);

 	if (karg.vma_name_size && copy_to_user(u64_to_user_ptr(karg.vma_name_addr),
 					       name, karg.vma_name_size)) {
 		kfree(name_buf);
 		return -EFAULT;
 	}
 	kfree(name_buf);

 	if (karg.build_id_size && copy_to_user(u64_to_user_ptr(karg.build_id_addr),
 					       build_id_buf, karg.build_id_size))
 		return -EFAULT;

 	if (copy_to_user(uarg, &karg, min_t(size_t, sizeof(karg), usize)))
 		return -EFAULT;

 	return 0;

 out:
 	query_vma_teardown(&lock_ctx);
 	mmput(mm);
+out_file:
 	if (vm_file)
 		fput(vm_file);
 	kfree(name_buf);
 	return err;
 }



